+export function problem(status: number, title: string, detail?: string, extra: Record<string, unknown> = {}) {
+  const body: Problem = {
+    type: `https://safekeep.local/problems/${title.toLowerCase().replaceAll(/[^a-z0-9]+/g, "-")}`,
