"use client";

import { useRouter } from "next/navigation";
import { useEffect, useId, useState } from "react";
import type { Bookmark } from "@/features/bookmarks/types";
import { apiMutation } from "@/lib/http/client";
import { NoteEditor } from "./note-editor";

type Preview = {
  requestedUrl: string;
  title: string;
  pageDescription: string | null;
  iconPreviewKey: string | null;
  status: "complete" | "partial" | "failed";
  warnings: string[];
};

function fallbackPreview(url: string, warning: string): Preview {
  let title = url;
  try { const parsed = new URL(/^https?:/i.test(url) ? url : `https://${url}`); title = parsed.hostname.replace(/^www\./, ""); } catch { /* keep input */ }
  return { requestedUrl: url, title, pageDescription: null, iconPreviewKey: null, status: "failed", warnings: [warning] };
}

export function BookmarkEditor({ existing }: { existing?: Bookmark }) {
  const router = useRouter();
  const titleId = useId();
  const [open, setOpen] = useState(false);
  const [url, setUrl] = useState(existing?.url ?? "");
  const [preview, setPreview] = useState<Preview | null>(existing ? {
    requestedUrl: existing.url, title: existing.title, pageDescription: existing.pageDescription,
    iconPreviewKey: existing.iconKey, status: existing.metadataStatus === "not_requested" ? "partial" : existing.metadataStatus,
    warnings: [],
  } : null);
  const [title, setTitle] = useState(existing?.title ?? "");
  const [description, setDescription] = useState(existing?.pageDescription ?? "");
  const [tags, setTags] = useState(existing?.tags.join(", ") ?? "");
  const [readLater, setReadLater] = useState(existing?.readingState === "unread");
  const [note, setNote] = useState(existing?.noteMarkdown ?? "");
  const [pending, setPending] = useState(false);
  const [message, setMessage] = useState("");

  useEffect(() => {
    if (!open) setMessage("");
  }, [open]);

  async function fetchDetails() {
    setPending(true); setMessage("");
    try {
      const result = await apiMutation<Preview>("/api/metadata/preview", "POST", { url });
      setPreview(result); setUrl(result.requestedUrl); setTitle(result.title); setDescription(result.pageDescription ?? "");
    } catch (cause) {
      const error = cause as Error & { status?: number; data?: Record<string, unknown> };
      if (error.status === 409 && error.data?.existingBookmarkId) {
        setOpen(false);
        router.push(`${error.data.existingView === "archive" ? "/archive" : "/bookmarks"}?focus=${String(error.data.existingBookmarkId)}`);
        return;
      }
      const fallback = fallbackPreview(url, `${error.message} You can still save this link.`);
      setPreview(fallback); setTitle(fallback.title); setMessage(fallback.warnings[0]!);
    } finally { setPending(false); }
  }

  async function save(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); setPending(true); setMessage("");
    const body = {
      url,
      title,
      pageDescription: description || null,
      iconPreviewKey: preview?.iconPreviewKey ?? null,
      metadataStatus: preview?.status ?? "not_requested",
      tags: tags.split(",").map((tag) => tag.trim()).filter(Boolean),
      readingState: readLater ? "unread" : existing?.readingState ?? "none",
      noteMarkdown: note || null,
    };
    try {
      if (existing) await apiMutation(`/api/bookmarks/${existing.id}`, "PATCH", body);
      else await apiMutation("/api/bookmarks", "POST", body);
      setOpen(false); router.refresh();
      if (!existing) { setUrl(""); setTitle(""); setDescription(""); setTags(""); setPreview(null); setReadLater(false); setNote(""); }
    } catch (cause) {
      const error = cause as Error & { status?: number; data?: Record<string, unknown> };
      if (error.status === 409 && error.data?.existingBookmarkId) {
        setOpen(false);
        router.push(`${error.data.existingView === "archive" ? "/archive" : "/bookmarks"}?focus=${String(error.data.existingBookmarkId)}`);
      } else setMessage(error.message);
    } finally { setPending(false); }
  }

  return (
    <>
      <button className={existing ? "icon-button" : "button"} type="button" onClick={() => setOpen(true)} aria-label={existing ? `Edit ${existing.title}` : undefined}>{existing ? "Edit" : "+ Save a link"}</button>
      {open ? (
        <div className="dialog-backdrop" onMouseDown={(event) => { if (event.currentTarget === event.target) setOpen(false); }}>
          <section className="editor-dialog" role="dialog" aria-modal="true" aria-labelledby={titleId}>
            <div className="dialog-heading"><div><p className="eyebrow">{existing ? "Update bookmark" : "New bookmark"}</p><h2 id={titleId}>{existing ? "Edit the details" : preview ? "Make it yours" : "Paste a link"}</h2></div><button className="close-button" type="button" onClick={() => setOpen(false)} aria-label="Close">×</button></div>
            {!preview && !existing ? (
              <div className="stack">
                <div className="field"><label htmlFor="capture-url">Web address</label><input className="input url-input" id="capture-url" value={url} onChange={(event) => setUrl(event.target.value)} placeholder="https://example.com/article" autoFocus /></div>
                <p className="muted small">We’ll fill in the title, description, and site icon. If the page is slow or blocks us, you can still save it.</p>
                {message ? <div className="form-message error" role="alert">{message}</div> : null}
                <button className="button" type="button" disabled={pending || !url.trim()} onClick={fetchDetails}>{pending ? "Looking up the page…" : "Fetch page details"}</button>
              </div>
            ) : (
              <form className="stack" onSubmit={save}>
                <div className="field"><label htmlFor="edit-url">Web address</label><div className="inline-field"><input className="input" id="edit-url" value={url} onChange={(event) => setUrl(event.target.value)} required maxLength={4096} />{!existing ? <button className="button secondary" type="button" onClick={fetchDetails} disabled={pending}>Refresh</button> : null}</div></div>
                <div className="field"><label htmlFor="edit-title">Title</label><input className="input" id="edit-title" value={title} onChange={(event) => setTitle(event.target.value)} required maxLength={500} /></div>
                <div className="field"><label htmlFor="edit-description">Page description</label><textarea className="textarea compact" id="edit-description" value={description} onChange={(event) => setDescription(event.target.value)} maxLength={2000} placeholder="Optional" /></div>
                <div className="field"><label htmlFor="edit-tags">Tags</label><input className="input" id="edit-tags" value={tags} onChange={(event) => setTags(event.target.value)} placeholder="design, research, recipes" /><small className="muted">Separate tags with commas.</small></div>
                <div className="field"><span className="field-label">Personal notes</span><NoteEditor value={note} onChange={setNote} /></div>
                <label className="check-row"><input type="checkbox" checked={readLater} onChange={(event) => setReadLater(event.target.checked)} /> Add to read later</label>
                {preview?.warnings.map((warning) => <div className="form-message" key={warning}>{warning}</div>)}
                {message ? <div className="form-message error" role="alert">{message}</div> : null}
                <div className="dialog-actions"><button className="button secondary" type="button" onClick={() => setOpen(false)}>Cancel</button><button className="button" type="submit" disabled={pending || !title.trim()}>{pending ? "Saving…" : existing ? "Save changes" : "Save bookmark"}</button></div>
              </form>
            )}
          </section>
        </div>
      ) : null}
    </>
  );
}
"use client";

import { useEffect, useState } from "react";
import { useRouter } from "next/navigation";
import type { Bookmark } from "@/features/bookmarks/types";
import type { BulkOperation } from "@/features/bookmarks/bulk-service";
import { apiMutation } from "@/lib/http/client";
import { BookmarkCard } from "./bookmark-card";
import { BulkToolbar } from "./bulk-toolbar";
import { DeleteConfirmation } from "./delete-confirmation";

export function SelectionController({ items, focus, signature }: { items: Bookmark[]; focus?: string; signature: string }) {
  const router = useRouter();
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [confirmDelete, setConfirmDelete] = useState(false);
  const [message, setMessage] = useState("");
  useEffect(() => { setSelected(new Set()); }, [signature]);
  const ids = [...selected];
  async function apply(operation: BulkOperation, tags?: string[]) {
    if (operation === "permanent_delete") { setConfirmDelete(true); return; }
    try {
      const result = await apiMutation<{ succeededIds: string[]; failures: unknown[] }>("/api/bookmarks/bulk", "POST", { ids, operation, tagNames: tags });
      setMessage(`${result.succeededIds.length} ${result.succeededIds.length === 1 ? "bookmark" : "bookmarks"} updated.${result.failures.length ? ` ${result.failures.length} could not be updated.` : ""}`);
      setSelected(new Set()); router.refresh();
    } catch (cause) { setMessage(cause instanceof Error ? cause.message : "Nothing changed. Please try again."); }
  }
  return (
    <>
      <div className="selection-row"><label><input type="checkbox" checked={items.length > 0 && selected.size === items.length} onChange={(event) => setSelected(event.target.checked ? new Set(items.slice(0, 100).map((item) => item.id)) : new Set())} /> Select all visible</label><span className="muted">Up to 100 at a time</span></div>
      {message ? <div className="form-message" role="status">{message}</div> : null}
      <div className="bookmark-list">{items.map((item) => <BookmarkCard key={item.id} bookmark={item} focused={focus === item.id} selected={selected.has(item.id)} onSelect={(checked) => setSelected((current) => { const next = new Set(current); if (checked && next.size < 100) next.add(item.id); else next.delete(item.id); return next; })} />)}</div>
      {selected.size ? <BulkToolbar count={selected.size} onApply={apply} onClear={() => setSelected(new Set())} /> : null}
      <DeleteConfirmation ids={ids} open={confirmDelete} onClose={() => { setConfirmDelete(false); setSelected(new Set()); }} />
    </>
  );
}
"use client";

import type { Bookmark } from "@/features/bookmarks/types";
import { BookmarkEditor } from "./bookmark-editor";
import { NoteRenderer } from "./note-renderer";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { apiMutation } from "@/lib/http/client";
import { DeleteConfirmation } from "./delete-confirmation";

export function BookmarkCard({ bookmark, focused = false, selected, onSelect }: { bookmark: Bookmark; focused?: boolean; selected?: boolean; onSelect?: (selected: boolean) => void }) {
  const router = useRouter();
  const [pending, setPending] = useState(false);
  const [deleting, setDeleting] = useState(false);
  async function update(body: Record<string, unknown>) {
    setPending(true);
    try { await apiMutation(`/api/bookmarks/${bookmark.id}`, "PATCH", body); router.refresh(); } finally { setPending(false); }
  }
  return (
    <article className={`bookmark-card${focused ? " focused" : ""}`} id={`bookmark-${bookmark.id}`}>
      {onSelect ? <label className="select-box"><span className="sr-only">Select {bookmark.title}</span><input type="checkbox" checked={selected} onChange={(event) => onSelect(event.target.checked)} /></label> : null}
      <img className="site-icon" src={bookmark.iconUrl} alt="" width={40} height={40} />
      <div className="bookmark-copy">
        <div className="bookmark-meta"><span>{bookmark.domain}</span><span>·</span><time dateTime={bookmark.createdAt}>{new Intl.DateTimeFormat("en", { dateStyle: "medium" }).format(new Date(bookmark.createdAt))}</time>{bookmark.readingState !== "none" ? <span className={`status ${bookmark.readingState}`}>{bookmark.readingState === "unread" ? "To read" : "Read"}</span> : null}</div>
        <h2><a href={bookmark.url} target="_blank" rel="noopener noreferrer" referrerPolicy="no-referrer">{bookmark.title}</a></h2>
        {bookmark.pageDescription ? <p>{bookmark.pageDescription}</p> : null}
        {bookmark.tags.length ? <div className="tag-list" aria-label="Tags">{bookmark.tags.map((tag) => <span className="tag" key={tag}>{tag}</span>)}</div> : null}
        {bookmark.noteMarkdown ? <details className="bookmark-notes"><summary>Personal notes</summary><NoteRenderer>{bookmark.noteMarkdown}</NoteRenderer></details> : null}
      </div>
      <div className="card-actions">
        <button className="icon-button" type="button" disabled={pending} onClick={() => update({ readingState: bookmark.readingState === "unread" ? "read" : "unread" })}>{bookmark.readingState === "unread" ? "Mark read" : "Read later"}</button>
        <button className="icon-button" type="button" disabled={pending} onClick={() => update({ archived: !bookmark.archived })}>{bookmark.archived ? "Restore" : "Archive"}</button>
        <BookmarkEditor existing={bookmark} />
        <button className="icon-button danger-text" type="button" onClick={() => setDeleting(true)}>Delete</button>
      </div>
      <DeleteConfirmation ids={[bookmark.id]} open={deleting} onClose={() => setDeleting(false)} />
    </article>
  );
}
import { randomUUID } from "node:crypto";
import type Database from "better-sqlite3";
import { getSqlite } from "@/lib/db/client";
import { parseSearchQuery } from "@/features/bookmarks/search-parser";
import { compileSearch } from "@/features/bookmarks/search-compiler";
import type { Bookmark, CollectionView, SortOrder } from "@/features/bookmarks/types";
import type { MetadataStatus, ReadingState } from "@/lib/db/schema";
import { assertOwnerScope } from "./owned-repository";
import { replaceBookmarkTags } from "./tag-repository";
import { syncBookmarkSearch } from "./search-repository";

type BookmarkRow = {
  id: string; url: string; normalized_url: string; title: string; page_description: string | null;
  icon_key: string | null; note_markdown: string | null; reading_state: ReadingState; archived_at: number | null;
  metadata_status: MetadataStatus; metadata_fetched_at: number | null; created_at: number; updated_at: number;
  tags: string | null;
};

function mapBookmark(row: BookmarkRow): Bookmark {
  return {
    id: row.id,
    url: row.url,
    normalizedUrl: row.normalized_url,
    title: row.title,
    pageDescription: row.page_description,
    iconKey: row.icon_key,
    iconUrl: `/api/bookmarks/${row.id}/icon`,
    noteMarkdown: row.note_markdown,
    readingState: row.reading_state,
    archived: row.archived_at !== null,
    archivedAt: row.archived_at ? new Date(row.archived_at).toISOString() : null,
    metadataStatus: row.metadata_status,
    metadataFetchedAt: row.metadata_fetched_at ? new Date(row.metadata_fetched_at).toISOString() : null,
    tags: row.tags ? row.tags.split("\u001f") : [],
    createdAt: new Date(row.created_at).toISOString(),
    updatedAt: new Date(row.updated_at).toISOString(),
    domain: new URL(row.url).hostname.replace(/^www\./, ""),
  };
}

const selectFields = `b.id, b.url, b.normalized_url, b.title, b.page_description, b.icon_key, b.note_markdown,
 b.reading_state, b.archived_at, b.metadata_status, b.metadata_fetched_at, b.created_at, b.updated_at,
 GROUP_CONCAT(t.display_name, char(31)) AS tags`;
const joins = `FROM bookmarks b LEFT JOIN bookmark_tags bt ON bt.bookmark_id = b.id LEFT JOIN tags t ON t.id = bt.tag_id`;

export function findBookmark(userId: string, id: string, sqlite = getSqlite()): Bookmark | null {
  assertOwnerScope({ userId });
  const row = sqlite.prepare(`SELECT ${selectFields} ${joins} WHERE b.user_id = ? AND b.id = ? GROUP BY b.id`).get(userId, id) as BookmarkRow | undefined;
  return row ? mapBookmark(row) : null;
}

export function findDuplicate(userId: string, normalizedUrl: string, excludeId?: string, sqlite = getSqlite()): Bookmark | null {
  const row = sqlite.prepare(`SELECT ${selectFields} ${joins} WHERE b.user_id = ? AND b.normalized_url = ? ${excludeId ? "AND b.id <> ?" : ""} GROUP BY b.id`).get(...(excludeId ? [userId, normalizedUrl, excludeId] : [userId, normalizedUrl])) as BookmarkRow | undefined;
  return row ? mapBookmark(row) : null;
}

export function listBookmarks(userId: string, options: { view?: CollectionView; q?: string; tag?: string; readingState?: ReadingState; sort?: SortOrder; limit?: number } = {}, sqlite = getSqlite()): Bookmark[] {
  assertOwnerScope({ userId });
  const view = options.view ?? "active";
  const conditions = ["b.user_id = ?"];
  const params: unknown[] = [userId];
  if (view === "archive") conditions.push("b.archived_at IS NOT NULL");
  else conditions.push("b.archived_at IS NULL");
  if (view === "unread") conditions.push("b.reading_state = 'unread'");
