import "server-only";
import { hash, verify } from "@node-rs/argon2";
import { betterAuth } from "better-auth";
import { drizzleAdapter } from "better-auth/adapters/drizzle";
import { nextCookies } from "better-auth/next-js";
import { getConfig } from "@/lib/config";
import { db } from "@/lib/db/client";
import { authSchema } from "@/lib/db/auth-schema";
import { getEmailSender } from "@/lib/email";

const config = getConfig();

export const auth = betterAuth({
  appName: "Safekeep",
  baseURL: config.APP_BASE_URL,
  secret: config.BETTER_AUTH_SECRET,
  trustedOrigins: [config.APP_BASE_URL, "http://maker:4000", "http://127.0.0.1:4000"],
  database: drizzleAdapter(db, {
    provider: "sqlite",
    schema: authSchema,
    transaction: true,
  }),
  emailAndPassword: {
    enabled: true,
    minPasswordLength: 12,
    maxPasswordLength: 128,
    requireEmailVerification: config.NODE_ENV === "production",
    revokeSessionsOnPasswordReset: true,
    resetPasswordTokenExpiresIn: 30 * 60,
    password: {
      hash: async (password) =>
        hash(password.normalize("NFC"), {
          memoryCost: 19 * 1024,
          timeCost: 2,
          parallelism: 1,
          outputLen: 32,
        }),
      verify: async ({ hash: digest, password }) => verify(digest, password.normalize("NFC")),
    },
    sendResetPassword: async ({ user, url }) => {
      await getEmailSender().send({
        to: user.email,
        subject: "Reset your Safekeep password",
        text: `Use this link within 30 minutes to reset your password: ${url}`,
      });
    },
  },
  emailVerification: {
    sendVerificationEmail: async ({ user, url }) => {
      await getEmailSender().send({
        to: user.email,
        subject: "Verify your Safekeep account",
        text: `Verify your email address: ${url}`,
      });
    },
    sendOnSignUp: config.NODE_ENV === "production",
    autoSignInAfterVerification: true,
  },
  session: {
    expiresIn: 60 * 60 * 24 * 30,
    updateAge: 60 * 60 * 24,
  },
  advanced: {
    useSecureCookies: config.NODE_ENV === "production",
    cookiePrefix: "safekeep",
  },
  plugins: [nextCookies()],
});

export type Session = typeof auth.$Infer.Session;
import { expect, test } from "@playwright/test";

async function signIn(page: import("@playwright/test").Page) {
  await page.goto("/sign-in");
  await page.getByLabel("Email").fill("review@example.com");
  await page.getByLabel("Password").fill("Review-password-2026!");
  await page.getByRole("button", { name: "Welcome back" }).click();
  await expect(page).toHaveURL(/\/bookmarks/);
}

test("review account can sign in and see the seeded collection", async ({ page }) => {
  await signIn(page);
  await expect(page.getByRole("heading", { name: "Bookmarks", exact: true })).toBeVisible();
  await expect(page.getByRole("link", { name: "Accessibility on the web" })).toBeVisible();
  await expect(page.locator('[data-harness-ready="true"]')).toBeVisible();
});

test("user can fetch details and save a URL-only bookmark", async ({ page }) => {
  await signIn(page);
  const uniqueUrl = `https://example.com/?smoke=${Date.now()}`;
  await page.getByRole("button", { name: "+ Save a link" }).first().click();
  await page.getByLabel("Web address").fill(uniqueUrl);
  await page.getByRole("button", { name: "Fetch page details" }).click();
  await expect(page.getByLabel("Title")).toBeVisible({ timeout: 10_000 });
  const title = await page.getByLabel("Title").inputValue();
  expect(title.length).toBeGreaterThan(0);
  await page.getByLabel("Add to read later").check();
  await page.getByRole("button", { name: "Save bookmark" }).click();
  await expect(page.getByRole("link", { name: title })).toBeVisible();
});
"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth/client";
import { RECOVERY_MESSAGE } from "@/lib/auth/recovery";

type Mode = "sign-in" | "sign-up" | "forgot" | "reset";

export function AuthForm({ mode, resetToken }: { mode: Mode; resetToken?: string }) {
  const router = useRouter();
  const [pending, setPending] = useState(false);
  const [message, setMessage] = useState("");
  const [error, setError] = useState("");

  async function onSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setPending(true);
    setError("");
    setMessage("");
    const data = new FormData(event.currentTarget);
    const email = String(data.get("email") ?? "");
    const password = String(data.get("password") ?? "");
    const name = String(data.get("name") ?? "");
    try {
      if (mode === "sign-in") {
        const result = await authClient.signIn.email({ email, password, callbackURL: "/bookmarks" });
        if (result.error) throw new Error(result.error.message ?? "Unable to sign in.");
        router.push("/bookmarks");
        router.refresh();
      } else if (mode === "sign-up") {
        const result = await authClient.signUp.email({ email, password, name, callbackURL: "/bookmarks" });
        if (result.error) throw new Error(result.error.message ?? "Unable to create the account.");
        router.push("/bookmarks");
        router.refresh();
      } else if (mode === "forgot") {
        await authClient.requestPasswordReset({ email, redirectTo: "/reset-password" });
        setMessage(RECOVERY_MESSAGE);
      } else {
        const token = resetToken;
        if (!token) throw new Error("This reset link is incomplete. Request a new one.");
        const result = await authClient.resetPassword({ newPassword: password, token });
        if (result.error) throw new Error(result.error.message ?? "Unable to reset the password.");
        setMessage("Your password has been reset. You can sign in now.");
      }
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Something went wrong. Please try again.");
    } finally {
      setPending(false);
    }
  }

  const title = {
    "sign-in": "Welcome back",
    "sign-up": "Create your collection",
    forgot: "Reset your password",
    reset: "Choose a new password",
  }[mode];

  return (
    <main className="auth-page" data-harness-ready="true">
      <section className="auth-card" aria-labelledby="auth-title">
        <div className="brand">Safekeep</div>
